    WorktreeError,
};
use parking_lot::Mutex;
use std::collections::HashMap;
use std::fs;
use std::path::{Component, Path, PathBuf};
use std::sync::Arc;

const ORCA_WORKTREE_DIR: &str = ".orca-worktrees";

#[derive(Debug, Clone, Default)]
pub struct WriterLeaseRegistry {
    writers: Arc<Mutex<HashMap<PathBuf, String>>>,
}

impl WriterLeaseRegistry {
    fn acquire_canonical(&self, path: PathBuf, owner_id: &str) -> Result<(), WorktreeError> {
        let mut writers = self.writers.lock();
        if let Some(existing_owner) = writers.get(&path) {
            return Err(WorktreeError::WriterAlreadyActive {
                path,
                owner_id: existing_owner.clone(),
            });
        }
        writers.insert(path, owner_id.to_string());
        Ok(())
    }

    fn release_canonical(&self, path: &Path, owner_id: &str) -> Result<(), WorktreeError> {
        let mut writers = self.writers.lock();
        let Some(existing_owner) = writers.get(path) else {
            return Ok(());
        };
        if existing_owner != owner_id {
            return Err(WorktreeError::WriterLeaseOwnerMismatch {
                path: path.to_path_buf(),
                owner_id: existing_owner.clone(),
                requested_owner_id: owner_id.to_string(),
            });
        }
        writers.remove(path);
        Ok(())
    }

    fn owner_canonical(&self, path: &Path) -> Option<String> {
        self.writers.lock().get(path).cloned()
    }
}

#[derive(Debug)]
pub(crate) struct WriterLeaseGuard {
    registry: WriterLeaseRegistry,
    canonical_path: PathBuf,
    owner_id: String,
}

impl WriterLeaseGuard {
    fn new(registry: WriterLeaseRegistry, canonical_path: PathBuf, owner_id: String) -> Self {
        Self {
            registry,
            canonical_path,
            owner_id,
        }
    }

    pub(crate) fn canonical_path(&self) -> &Path {
        &self.canonical_path
    }

    pub(crate) fn owner_id(&self) -> &str {
        &self.owner_id
    }
}

impl Drop for WriterLeaseGuard {
    fn drop(&mut self) {
        let _ = self
            .registry
            .release_canonical(&self.canonical_path, &self.owner_id);
    }
}

/// Manages Git worktrees under a canonical repository root.
///
/// Every filesystem path accepted by this manager must stay inside `repo_root` after
/// canonicalization. Construction accepts either that root or any directory within it,
/// then resolves the canonical root. IPC callers should prefer identity-based resolution
/// through `WorkspaceRegistry` instead of passing paths directly.
#[derive(Debug, Clone)]
pub struct WorktreeManager {
    repo_root: PathBuf,
    writer_leases: WriterLeaseRegistry,
    delete_lock: Arc<Mutex<()>>,
    dirty_snapshots: Arc<Mutex<HashMap<PathBuf, bool>>>,
}

impl WorktreeManager {
    /// Creates a manager and immediately validates/canonicalizes the Git repository root.
    /// Invalid roots are programmer configuration errors; fallible callers should use `try_new`.
    pub fn new(repo_root: impl Into<PathBuf>) -> Self {
        let requested = repo_root.into();
        Self::try_new(&requested)
            .unwrap_or_else(|error| panic!("invalid worktree manager root '{}': {error}", requested.display()))
    }

    pub fn try_new(repo_root: impl Into<PathBuf>) -> Result<Self, WorktreeError> {
        let requested = repo_root.into();
        let canonical = fs::canonicalize(&requested)
            .map_err(|_| WorktreeError::InvalidRepoRoot {
                path: requested.clone(),
            })?;
        if !canonical.is_dir() {
            return Err(WorktreeError::InvalidRepoRoot { path: canonical });
        }

        let top_level = run_git(&canonical, &["rev-parse", "--show-toplevel"])
            .map_err(|_| WorktreeError::InvalidRepoRoot {
                path: canonical.clone(),
            })?;
        let git_root = fs::canonicalize(PathBuf::from(top_level.trim())).map_err(|_| {
            WorktreeError::InvalidRepoRoot {
                path: canonical.clone(),
            }
        })?;
        Ok(Self {
            repo_root: git_root,
            writer_leases: WriterLeaseRegistry::default(),
            delete_lock: Arc::new(Mutex::new(())),
            dirty_snapshots: Arc::new(Mutex::new(HashMap::new())),
        })
    }

    pub fn repo_root(&self) -> &Path {
        &self.repo_root
    }

    fn validate_path_components(&self, path: &Path) -> Result<(), WorktreeError> {
        if !path.is_absolute() {
            return Err(WorktreeError::InvalidPath {
                path: path.to_path_buf(),
                reason: "path must be absolute".into(),
            });
        }
        if path.components().any(|component| matches!(component, Component::ParentDir)) {
            return Err(WorktreeError::InvalidPath {
                path: path.to_path_buf(),
                reason: "parent traversal ('..') is forbidden".into(),
            });
        }
        if let Some(name) = path.file_name().and_then(|name| name.to_str()) {
            if name.starts_with('-') {
                return Err(WorktreeError::InvalidPath {
                    path: path.to_path_buf(),
                    reason: "path component cannot start with a dash".into(),
                });
            }
            if name.chars().any(char::is_control) {
                return Err(WorktreeError::InvalidPath {
                    path: path.to_path_buf(),
                    reason: "path component cannot contain control characters".into(),
                });
            }
        }
        Ok(())
    }

    fn ensure_canonical_inside_root(
        &self,
        original: &Path,
        canonical: PathBuf,
    ) -> Result<PathBuf, WorktreeError> {
        if canonical == self.repo_root || canonical.starts_with(&self.repo_root) {
            Ok(canonical)
        } else {
            Err(WorktreeError::PathOutsideWorkspace {
                path: original.to_path_buf(),
                root: self.repo_root.clone(),
            })
        }
    }

    pub fn canonical_allowed_path(&self, path: &Path) -> Result<PathBuf, WorktreeError> {
        self.validate_path_components(path)?;
        let canonical = fs::canonicalize(path).map_err(|_| WorktreeError::WorktreeNotFound {
            path: path.to_path_buf(),
        })?;
        self.ensure_canonical_inside_root(path, canonical)
    }

    fn validate_new_worktree_path(&self, path: &Path) -> Result<(), WorktreeError> {
        self.validate_path_components(path)?;
        if !path.starts_with(&self.repo_root) {
            return Err(WorktreeError::PathOutsideWorkspace {
                path: path.to_path_buf(),
                root: self.repo_root.clone(),
            });
        }

        let mut ancestor = path.parent().ok_or_else(|| WorktreeError::InvalidPath {
            path: path.to_path_buf(),
            reason: "worktree target has no parent".into(),
        })?;
        while !ancestor.exists() {
            ancestor = ancestor.parent().ok_or_else(|| WorktreeError::InvalidPath {
                path: path.to_path_buf(),
                reason: "worktree target has no existing ancestor".into(),
            })?;
        }
        let canonical_ancestor = fs::canonicalize(ancestor)?;
        self.ensure_canonical_inside_root(path, canonical_ancestor)?;
        Ok(())
    }

    fn canonical_worktree_path(&self, path: &Path) -> Result<PathBuf, WorktreeError> {
        self.canonical_allowed_path(path)
    }

    pub fn worktree_path_for(&self, ws_id: &str, slug: &str) -> Result<PathBuf, WorktreeError> {
        Self::format_branch_name(ws_id, slug)?;
        let mut target = self.repo_root.join(ORCA_WORKTREE_DIR).join(ws_id);
        for segment in slug.split('/') {
            target.push(segment);
        }
        self.validate_new_worktree_path(&target)?;
        Ok(target)
    }

    pub fn acquire_writer(&self, worktree_path: &Path, owner_id: &str) -> Result<(), WorktreeError> {
        let _delete_guard = self.delete_lock.lock();
        let canonical = self.canonical_worktree_path(worktree_path)?;
        self.writer_leases.acquire_canonical(canonical, owner_id)
    }

    pub fn release_writer(&self, worktree_path: &Path, owner_id: &str) -> Result<(), WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        self.writer_leases.release_canonical(&canonical, owner_id)
    }

    pub fn writer_owner(&self, worktree_path: &Path) -> Result<Option<String>, WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        Ok(self.writer_leases.owner_canonical(&canonical))
    }

    pub(crate) fn acquire_writer_lease(
        &self,
        worktree_path: &Path,
        owner_id: &str,
    ) -> Result<WriterLeaseGuard, WorktreeError> {
        let _delete_guard = self.delete_lock.lock();
        let canonical = self.canonical_worktree_path(worktree_path)?;
        self.writer_leases
            .acquire_canonical(canonical.clone(), owner_id)?;
        Ok(WriterLeaseGuard::new(
            self.writer_leases.clone(),
            canonical,
            owner_id.to_string(),
        ))
    }

    pub fn format_branch_name(ws_id: &str, slug: &str) -> Result<String, WorktreeError> {
        let ws_id = ws_id.trim();
        let slug = slug.trim();
        if ws_id.is_empty() {
            return Err(WorktreeError::InvalidNamespace {
                reason: "Workspace ID cannot be empty".into(),
            });
        }
        if slug.is_empty() {
            return Err(WorktreeError::InvalidNamespace {
                reason: "Slug cannot be empty".into(),
            });
        }
        if ws_id.contains('/') {
            return Err(WorktreeError::InvalidNamespace {
                reason: "Workspace ID cannot contain '/'".into(),
            });
        }
        Self::validate_ref_component(ws_id, "workspace ID")?;
        Self::validate_ref_component(slug, "slug")?;
        Ok(format!("orca/{ws_id}/{slug}"))
    }

    pub fn parse_branch_name(branch: &str) -> Option<OrcaWorktreeInfo> {
        let short = branch.strip_prefix("refs/heads/").unwrap_or(branch);
        let parts: Vec<&str> = short.split('/').collect();
        if parts.len() >= 3 && parts[0] == "orca" {
            Some(OrcaWorktreeInfo {
                ws_id: parts[1].to_string(),
                slug: parts[2..].join("/"),
            })
        } else {
            None
        }
    }

    fn validate_ref_component(component: &str, label: &str) -> Result<(), WorktreeError> {
        if component.contains("..") || component.contains("//") || component.contains("@{") {
            return Err(WorktreeError::InvalidNamespace {
                reason: format!("{label} cannot contain '..', '//', or '@{{'"),
            });
        }

        for segment in component.split('/') {
            if segment.is_empty()
                || segment.starts_with('.')
                || segment.ends_with('.')
                || segment.starts_with('-')
            {
                return Err(WorktreeError::InvalidNamespace {
                    reason: format!(
                        "{label} path segments cannot be empty or start/end with '.', or start with '-'"
                    ),
                });
            }
            if segment.ends_with(".lock") {
                return Err(WorktreeError::InvalidNamespace {
                    reason: format!("{label} cannot end with '.lock'"),
                });
            }
            for ch in segment.chars() {
                if ch.is_ascii_control()
                    || ch.is_whitespace()
                    || matches!(ch, '~' | '^' | ':' | '?' | '*' | '[' | '\\')
                {
                    return Err(WorktreeError::InvalidNamespace {
                        reason: format!("{label} contains invalid character '{ch}'"),
                    });
                }
            }
        }
        Ok(())
    }

    pub fn create_worktree(
        &self,
        options: CreateWorktreeOptions,
    ) -> Result<Worktree, WorktreeError> {
        let branch_name = Self::format_branch_name(&options.ws_id, &options.slug)?;
        self.validate_new_worktree_path(&options.path)?;
        if options.path.exists() {
            self.canonical_allowed_path(&options.path)?;
            return Err(WorktreeError::WorktreeAlreadyExists { path: options.path });
        }

        let parent = options
            .path
            .parent()
            .ok_or_else(|| WorktreeError::InvalidPath {
                path: options.path.clone(),
                reason: "worktree target has no parent".into(),
            })?;
        fs::create_dir_all(parent)?;
        let canonical_parent = fs::canonicalize(parent)?;
        self.ensure_canonical_inside_root(&options.path, canonical_parent)?;

        git_worktree_add(
            &self.repo_root,
            &options.path,
            &branch_name,
            options.base_ref.as_deref(),
        )?;

        let target_canonical = self.canonical_allowed_path(&options.path)?;
        for wt in self.list_worktrees()? {
            if let Ok(wt_canonical) = self.canonical_allowed_path(&wt.path) {
                if wt_canonical == target_canonical {
                    return Ok(wt);
                }
            }
        }

        Ok(Worktree {
            path: target_canonical,
            head: String::new(),
            branch: Some(format!("refs/heads/{branch_name}")),
            bare: false,
            detached: false,
            locked: None,
            prunable: None,
        })
    }

    pub fn list_worktrees(&self) -> Result<Vec<Worktree>, WorktreeError> {
        let worktrees = git_worktree_list(&self.repo_root)?;
        Ok(worktrees
            .into_iter()
            .filter_map(|mut wt| {
                let canonical = self.canonical_allowed_path(&wt.path).ok()?;
                wt.path = canonical;
                Some(wt)
            })
            .collect())
    }

    pub fn find_worktree(&self, path: &Path) -> Result<Option<Worktree>, WorktreeError> {
        let target_canonical = self.canonical_allowed_path(path)?;
        for wt in self.list_worktrees()? {
            if wt.path == target_canonical {
                return Ok(Some(wt));
            }
        }
        Ok(None)
    }

    pub fn find_worktree_by_slug(
        &self,
        ws_id: &str,
        slug: &str,
    ) -> Result<Option<Worktree>, WorktreeError> {
        let target_branch = Self::format_branch_name(ws_id, slug)?;
        for wt in self.list_worktrees()? {
            if wt.branch_short_name() == Some(target_branch.as_str()) {
                return Ok(Some(wt));
            }
        }
        Ok(None)
    }

    pub fn check_dirty(&self, worktree_path: &Path) -> Result<DirtyState, WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        git_status_porcelain(&canonical)
    }

    pub fn observe_dirty_state(
        &self,
        worktree_path: &Path,
    ) -> Result<(DirtyState, bool), WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        let state = git_status_porcelain(&canonical)?;
        let previous = self
            .dirty_snapshots
            .lock()
            .insert(canonical, state.is_dirty);
        let changed = matches!(previous, Some(previous_dirty) if previous_dirty != state.is_dirty);
        Ok((state, changed))
    }

    pub fn is_dirty(&self, worktree_path: &Path) -> Result<bool, WorktreeError> {
        self.check_dirty(worktree_path).map(|state| state.is_dirty)
    }

    fn ensure_no_writer(&self, worktree_path: &Path) -> Result<(), WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        if let Some(owner_id) = self.writer_leases.owner_canonical(&canonical) {
            return Err(WorktreeError::WriterAlreadyActive {
                path: canonical,
                owner_id,
            });
        }
        Ok(())
    }

    fn remove_worktree_locked(
        &self,
        worktree_path: &Path,
        force: bool,
    ) -> Result<bool, WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        self.ensure_no_writer(&canonical)?;
        let dirty_state = self.check_dirty(&canonical)?;
        if dirty_state.is_dirty {
            let count = dirty_state.files.len();
            let files = dirty_state.files.into_iter().map(|file| file.path).collect();
            return Err(WorktreeError::DirtyWorktree {
                path: canonical,
                count,
                files,
            });
        }

        git_worktree_remove(&self.repo_root, &canonical, force)?;
        self.dirty_snapshots.lock().remove(&canonical);
        Ok(git_worktree_prune(&self.repo_root).is_ok())
    }

    pub fn remove_worktree(&self, worktree_path: &Path, force: bool) -> Result<(), WorktreeError> {
        let _delete_guard = self.delete_lock.lock();
        self.remove_worktree_locked(worktree_path, force).map(|_| ())
    }

    pub fn safe_delete(&self, worktree_path: &Path) -> Result<(), WorktreeError> {
        self.remove_worktree(worktree_path, false)
    }

    fn branch_is_merged(&self, branch: &str) -> Result<bool, WorktreeError> {
        let merged = run_git(
            &self.repo_root,
            &["branch", "--merged", "HEAD", "--format=%(refname:short)"],
        )?;
        Ok(merged.lines().any(|line| line.trim() == branch))
    }

    pub fn branch_deletion_preview(
        &self,
        worktree_path: &Path,
    ) -> Result<BranchDeletionPreview, WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        let existing = self
            .find_worktree(&canonical)?
            .ok_or_else(|| WorktreeError::WorktreeNotFound {
                path: canonical.clone(),
            })?;
        let branch = existing
            .branch_short_name()
            .ok_or_else(|| WorktreeError::ParseError("Detached worktree has no branch".into()))?
            .to_string();
        let head = if existing.head.is_empty() {
            run_git(&self.repo_root, &["rev-parse", "--verify", &branch])?
                .trim()
                .to_string()
        } else {
            existing.head
        };
        let merged = self.branch_is_merged(&branch)?;
        let upstream = run_git(
            &self.repo_root,
            &["rev-parse", "--abbrev-ref", &format!("{branch}@{{upstream}}")],
        )
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());

        let (ahead, behind) = if let Some(upstream_ref) = upstream.as_deref() {
            let counts = run_git(
                &self.repo_root,
                &[
                    "rev-list",
                    "--left-right",
                    "--count",
                    &format!("{upstream_ref}...{branch}"),
                ],
            )?;
            let mut values = counts.split_whitespace();
            let behind = values.next().and_then(|value| value.parse::<u64>().ok());
            let ahead = values.next().and_then(|value| value.parse::<u64>().ok());
            (ahead, behind)
        } else {
            (None, None)
        };

        Ok(BranchDeletionPreview {
            branch,
            head,
            upstream,
            merged,
            ahead,
            behind,
        })
    }

    fn delete_worktree_and_branch_inner(
        &self,
        worktree_path: &Path,
        delete_branch: bool,
        destructive: bool,
    ) -> Result<bool, WorktreeError> {
        let _delete_guard = self.delete_lock.lock();
        self.ensure_no_writer(worktree_path)?;

        let branch = if delete_branch {
            let preview = self.branch_deletion_preview(worktree_path)?;
            if !destructive && !preview.merged {
                return Err(WorktreeError::UnmergedBranch {
                    branch: preview.branch,
                    head: preview.head,
                });
            }
            Some(preview.branch)
        } else {
            None
        };

        let pruned = self.remove_worktree_locked(worktree_path, false)?;
        if let Some(branch) = branch {
            git_branch_delete(&self.repo_root, &branch, destructive)?;
        }
        Ok(pruned)
    }

    pub(crate) fn delete_worktree_and_branch_with_prune_status(
        &self,
        worktree_path: &Path,
        delete_branch: bool,
        destructive: bool,
    ) -> Result<bool, WorktreeError> {
        self.delete_worktree_and_branch_inner(worktree_path, delete_branch, destructive)
    }

    pub fn delete_worktree_and_branch(
        &self,
        worktree_path: &Path,
        delete_branch: bool,
    ) -> Result<(), WorktreeError> {
        self.delete_worktree_and_branch_inner(worktree_path, delete_branch, false)
            .map(|_| ())
    }

    pub fn delete_worktree_and_branch_destructive(
        &self,
        worktree_path: &Path,
        delete_branch: bool,
    ) -> Result<(), WorktreeError> {
        self.delete_worktree_and_branch_inner(worktree_path, delete_branch, true)
            .map(|_| ())
    }
}

use crate::worktree::model::{DirtyFile, DirtyState, Worktree, WorktreeError};
use std::path::{Path, PathBuf};
use std::process::Command;

fn escape_git_arg_for_log(arg: &str) -> String {
    let mut escaped = String::with_capacity(arg.len());
    for ch in arg.chars() {
        match ch {
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            ch if ch.is_control() => {
                use std::fmt::Write as _;
                let _ = write!(&mut escaped, "\\u{{{:x}}}", ch as u32);
            }
            ch => escaped.push(ch),
        }
    }
    escaped
}

fn validate_git_value(value: &str, label: &str) -> Result<(), WorktreeError> {
    if value.is_empty() {
        return Err(WorktreeError::InvalidNamespace {
            reason: format!("{label} cannot be empty"),
        });
    }
    if value.starts_with('-') {
        return Err(WorktreeError::InvalidNamespace {
            reason: format!("{label} cannot start with a dash"),
        });
    }
    if value.chars().any(char::is_control) {
        return Err(WorktreeError::InvalidNamespace {
            reason: format!("{label} cannot contain control characters"),
        });
    }
    Ok(())
}

fn validate_git_path_argument(path: &Path) -> Result<&str, WorktreeError> {
    let path_str = path
        .to_str()
        .ok_or_else(|| WorktreeError::ParseError("Invalid UTF-8 in worktree path".into()))?;
    if path_str.starts_with('-') {
        return Err(WorktreeError::InvalidPath {
            path: path.to_path_buf(),
            reason: "Git path argument cannot start with a dash".into(),
        });
    }
    if path_str.chars().any(char::is_control) {
        return Err(WorktreeError::InvalidPath {
            path: path.to_path_buf(),
            reason: "Git path argument cannot contain control characters".into(),
        });
    }
    Ok(path_str)
}

fn validate_base_ref(repo_root: &Path, base_ref: &str) -> Result<(), WorktreeError> {
    validate_git_value(base_ref, "Base ref")?;
    let commit_ref = format!("{base_ref}^{{commit}}");
    run_git(
        repo_root,
        &["rev-parse", "--verify", "--quiet", commit_ref.as_str()],
    )?;
    Ok(())
}

/// Executes a git command in the specified directory.
pub fn run_git<P: AsRef<Path>, S: AsRef<str>>(
    cwd: P,
    args: &[S],
) -> Result<String, WorktreeError> {
    let cwd_path = cwd.as_ref();
    let arg_strs: Vec<&str> = args.iter().map(|s| s.as_ref()).collect();
    let command_str = format!(
        "git {}",
        arg_strs
            .iter()
            .map(|arg| escape_git_arg_for_log(arg))
            .collect::<Vec<_>>()
            .join(" ")
    );

    let output = Command::new("git")
        .args(&arg_strs)
        .current_dir(cwd_path)
        .output()
        .map_err(WorktreeError::Io)?;

    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).to_string();

    if !output.status.success() {
        return Err(WorktreeError::GitError {
            command: command_str,
            stderr: stderr.trim().to_string(),
            stdout: stdout.trim().to_string(),
            code: output.status.code(),
        });
    }

    Ok(stdout)
}

/// Parses the output of `git worktree list --porcelain`.
pub fn parse_worktree_list_porcelain(output: &str) -> Result<Vec<Worktree>, WorktreeError> {
    let mut worktrees = Vec::new();
    let mut current_path: Option<PathBuf> = None;
    let mut current_head = String::new();
    let mut current_branch: Option<String> = None;
    let mut is_bare = false;
    let mut is_detached = false;
    let mut locked_reason: Option<String> = None;
    let mut prunable_reason: Option<String> = None;

    let flush = |worktrees: &mut Vec<Worktree>,
                 path: &mut Option<PathBuf>,
                 head: &mut String,
                 branch: &mut Option<String>,
                 bare: &mut bool,
                 detached: &mut bool,
                 locked: &mut Option<String>,
                 prunable: &mut Option<String>| {
        if let Some(p) = path.take() {
            worktrees.push(Worktree {
                path: p,
                head: std::mem::take(head),
                branch: branch.take(),
                bare: *bare,
                detached: *detached,
                locked: locked.take(),
                prunable: prunable.take(),
            });
            *bare = false;
            *detached = false;
        }
    };

    for line in output.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            flush(
                &mut worktrees,
                &mut current_path,
                &mut current_head,
                &mut current_branch,
                &mut is_bare,
                &mut is_detached,
                &mut locked_reason,
                &mut prunable_reason,
            );
            continue;
        }

        if let Some(path_str) = trimmed.strip_prefix("worktree ") {
            if current_path.is_some() {
                flush(
                    &mut worktrees,
                    &mut current_path,
                    &mut current_head,
                    &mut current_branch,
                    &mut is_bare,
                    &mut is_detached,
                    &mut locked_reason,
                    &mut prunable_reason,
                );
            }
            current_path = Some(PathBuf::from(path_str.trim()));
        } else if let Some(head_str) = trimmed.strip_prefix("HEAD ") {
            current_head = head_str.trim().to_string();
        } else if let Some(branch_str) = trimmed.strip_prefix("branch ") {
            current_branch = Some(branch_str.trim().to_string());
        } else if trimmed == "bare" {
            is_bare = true;
        } else if trimmed == "detached" {
            is_detached = true;
        } else if let Some(reason) = trimmed.strip_prefix("locked") {
            let reason_str = reason.trim();
            locked_reason = Some(if reason_str.is_empty() {
                "locked".to_string()
            } else {
                reason_str.to_string()
            });
        } else if let Some(reason) = trimmed.strip_prefix("prunable") {
            let reason_str = reason.trim();
            prunable_reason = Some(if reason_str.is_empty() {
                "prunable".to_string()
            } else {
                reason_str.to_string()
            });
        }
    }

    flush(
        &mut worktrees,
        &mut current_path,
        &mut current_head,
        &mut current_branch,
        &mut is_bare,
        &mut is_detached,
        &mut locked_reason,
        &mut prunable_reason,
    );

    Ok(worktrees)
}

/// Parses output from `git status --porcelain` or `git status --porcelain=v2`.
pub fn parse_status_porcelain(output: &str) -> DirtyState {
    let mut files = Vec::new();

    for line in output.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        if let Some(rest) = trimmed.strip_prefix("1 ") {
            let parts: Vec<&str> = rest.split_whitespace().collect();
            if parts.len() >= 8 {
                files.push(DirtyFile {
                    status_code: parts[0].to_string(),
                    path: parts[7..].join(" "),
                });
                continue;
            }
        }

        if let Some(rest) = trimmed.strip_prefix("2 ") {
            let parts: Vec<&str> = rest.split_whitespace().collect();
            if parts.len() >= 9 {
                files.push(DirtyFile {
                    status_code: parts[0].to_string(),
                    path: parts[8..].join(" "),
                });
                continue;
            }
        }

        if let Some(rest) = trimmed.strip_prefix("u ") {
            let parts: Vec<&str> = rest.split_whitespace().collect();
            if parts.len() >= 10 {
                files.push(DirtyFile {
                    status_code: parts[0].to_string(),
                    path: parts[9..].join(" "),
                });
                continue;
            }
        }

        if let Some(rest) = trimmed.strip_prefix("? ") {
            files.push(DirtyFile {
                status_code: "?".to_string(),
                path: rest.trim().to_string(),
            });
            continue;
        }

        if trimmed.starts_with("! ") {
            continue;
        }

        if line.len() >= 3 {
            let status_code = line[..2].to_string();
            let path = line[3..].trim().to_string();
            if !path.is_empty() {
                files.push(DirtyFile { status_code, path });
            }
        }
    }

    if files.is_empty() {
        DirtyState::clean()
    } else {
        DirtyState::dirty(files)
    }
}

pub fn git_worktree_add(
    repo_root: &Path,
    worktree_path: &Path,
    branch_name: &str,
    base_ref: Option<&str>,
) -> Result<(), WorktreeError> {
    validate_git_value(branch_name, "Branch name")?;
    let path_str = validate_git_path_argument(worktree_path)?;
    if let Some(base) = base_ref {
        validate_base_ref(repo_root, base)?;
    }

    let mut args = vec!["worktree", "add", "-b", branch_name, "--", path_str];
    if let Some(base) = base_ref {
        args.push(base);
    }
    run_git(repo_root, &args)?;
    Ok(())
}

pub fn git_worktree_list(repo_root: &Path) -> Result<Vec<Worktree>, WorktreeError> {
    let output = run_git(repo_root, &["worktree", "list", "--porcelain"])?;
    parse_worktree_list_porcelain(&output)
}

pub fn git_worktree_remove(
    repo_root: &Path,
    worktree_path: &Path,
    force: bool,
) -> Result<(), WorktreeError> {
    let path_str = validate_git_path_argument(worktree_path)?;
    let mut args = vec!["worktree", "remove"];
    if force {
        args.push("--force");
    }
    args.extend(["--", path_str]);
    run_git(repo_root, &args)?;
    Ok(())
}

pub fn git_worktree_prune(repo_root: &Path) -> Result<(), WorktreeError> {
    run_git(repo_root, &["worktree", "prune"])?;
    Ok(())
}

pub fn git_status_porcelain(worktree_path: &Path) -> Result<DirtyState, WorktreeError> {
    let output = run_git(worktree_path, &["status", "--porcelain"])?;
    Ok(parse_status_porcelain(&output))
}

pub fn git_branch_delete(
    repo_root: &Path,
    branch_name: &str,
    force: bool,
) -> Result<(), WorktreeError> {
    validate_git_value(branch_name, "Branch name")?;
    let flag = if force { "-D" } else { "-d" };
    run_git(repo_root, &["branch", flag, "--", branch_name])?;
    Ok(())
}

use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use thiserror::Error;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Worktree {
    pub path: PathBuf,
    pub head: String,
    pub branch: Option<String>,
    pub bare: bool,
    pub detached: bool,
    pub locked: Option<String>,
    pub prunable: Option<String>,
}

impl Worktree {
    /// Returns the short branch name if this worktree is checked out on a branch.
    /// For example, `refs/heads/orca/ws1/feat` -> `orca/ws1/feat`.
    pub fn branch_short_name(&self) -> Option<&str> {
        self.branch
            .as_deref()
            .map(|b| b.strip_prefix("refs/heads/").unwrap_or(b))
    }

    /// Extracts Orca workspace ID and slug if the worktree branch follows `orca/<ws-id>/<slug>`.
    pub fn orca_info(&self) -> Option<OrcaWorktreeInfo> {
        let branch = self.branch_short_name()?;
        let parts: Vec<&str> = branch.split('/').collect();
        if parts.len() >= 3 && parts[0] == "orca" {
            Some(OrcaWorktreeInfo {
                ws_id: parts[1].to_string(),
                slug: parts[2..].join("/"),
            })
        } else {
            None
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct OrcaWorktreeInfo {
    pub ws_id: String,
    pub slug: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct WorktreeIdentity {
    pub ws_id: String,
    pub slug: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DirtyFile {
    pub status_code: String,
    pub path: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DirtyState {
    pub is_dirty: bool,
    pub files: Vec<DirtyFile>,
}

impl DirtyState {
    pub fn clean() -> Self {
        Self {
            is_dirty: false,
            files: Vec::new(),
        }
    }

    pub fn dirty(files: Vec<DirtyFile>) -> Self {
        Self {
            is_dirty: !files.is_empty(),
            files,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CreateWorktreeOptions {
    pub ws_id: String,
    pub slug: String,
    pub path: PathBuf,
    pub base_ref: Option<String>,
}

impl CreateWorktreeOptions {
    pub fn new(ws_id: impl Into<String>, slug: impl Into<String>, path: impl Into<PathBuf>) -> Self {
        Self {
            ws_id: ws_id.into(),
            slug: slug.into(),
            path: path.into(),
            base_ref: None,
        }
    }

    pub fn with_base_ref(mut self, base_ref: impl Into<String>) -> Self {
        self.base_ref = Some(base_ref.into());
        self
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct BranchDeletionPreview {
    pub branch: String,
    pub head: String,
    pub upstream: Option<String>,
    pub merged: bool,
    pub ahead: Option<u64>,
    pub behind: Option<u64>,
}

#[derive(Debug, Error)]
pub enum WorktreeError {
    #[error("Git command failed ({command}): {stderr} (exit code: {code:?})")]
    GitError {
        command: String,
        stderr: String,
        stdout: String,
        code: Option<i32>,
    },

    #[error("Worktree at '{path}' is dirty ({count} uncommitted/untracked files); deletion forbidden for 1-writer-1-worktree isolation")]
    DirtyWorktree {
        path: PathBuf,
        count: usize,
        files: Vec<String>,
    },

    #[error("Worktree '{path}' already has active writer '{owner_id}'")]
    WriterAlreadyActive { path: PathBuf, owner_id: String },

    #[error("Writer lease for '{path}' is owned by '{owner_id}', not '{requested_owner_id}'")]
    WriterLeaseOwnerMismatch {
        path: PathBuf,
        owner_id: String,
        requested_owner_id: String,
    },

    #[error("Branch '{branch}' at {head} is not merged; use the explicit destructive deletion API")]
    UnmergedBranch { branch: String, head: String },

    #[error("Workspace '{workspace_id}' is not registered")]
    WorkspaceNotFound { workspace_id: String },

    #[error("Workspace '{workspace_id}' is already registered")]
    WorkspaceAlreadyRegistered { workspace_id: String },

    #[error("Worktree identity '{ws_id}/{slug}' was not found in workspace '{workspace_id}'")]
    WorktreeIdentityNotFound {
        workspace_id: String,
        ws_id: String,
        slug: String,
    },

    #[error("Path '{path}' escapes registered workspace root '{root}'")]
    PathOutsideWorkspace { path: PathBuf, root: PathBuf },

    #[error("Invalid path '{path}': {reason}")]
    InvalidPath { path: PathBuf, reason: String },

    #[error("Worktree not found at '{path}'")]
    WorktreeNotFound { path: PathBuf },

    #[error("Worktree already exists at target path '{path}'")]
    WorktreeAlreadyExists { path: PathBuf },

    #[error("Branch already exists: '{branch}'")]
    BranchAlreadyExists { branch: String },

    #[error("Invalid workspace ID or slug for branch namespace: {reason}")]
    InvalidNamespace { reason: String },

    #[error("Repository root invalid or not found at '{path}'")]
    InvalidRepoRoot { path: PathBuf },

    #[error("Failed to parse git output: {0}")]
    ParseError(String),

    #[error("IO error: {0}")]
    Io(#[from] std::io::Error),
}

use crate::worktree::{Worktree, WorktreeError, WorktreeIdentity, WorktreeManager};
use parking_lot::RwLock;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::Arc;

#[derive(Debug, Clone, Default)]
pub struct WorkspaceRegistry {
    workspaces: Arc<RwLock<HashMap<String, WorktreeManager>>>,
}

impl WorkspaceRegistry {
    pub fn new() -> Self {
        Self::default()
    }

    fn validate_workspace_id(workspace_id: &str) -> Result<&str, WorktreeError> {
        let workspace_id = workspace_id.trim();
        if workspace_id.is_empty() {
            return Err(WorktreeError::InvalidNamespace {
                reason: "Workspace registry ID cannot be empty".into(),
            });
        }
        if workspace_id.starts_with('-')
            || workspace_id.contains('/')
            || workspace_id.contains('\\')
            || workspace_id.chars().any(|ch| ch.is_control() || ch.is_whitespace())
        {
            return Err(WorktreeError::InvalidNamespace {
                reason: "Workspace registry ID contains unsafe characters".into(),
            });
        }
        Ok(workspace_id)
    }

    pub fn register(
        &self,
        workspace_id: impl AsRef<str>,
        repo_root: impl AsRef<Path>,
    ) -> Result<(), WorktreeError> {
        let workspace_id = Self::validate_workspace_id(workspace_id.as_ref())?.to_string();
        let manager = WorktreeManager::try_new(repo_root.as_ref().to_path_buf())?;
        let mut workspaces = self.workspaces.write();
        if let Some(existing) = workspaces.get(&workspace_id) {
            if existing.repo_root() == manager.repo_root() {
                return Ok(());
            }
            return Err(WorktreeError::WorkspaceAlreadyRegistered { workspace_id });
        }
        workspaces.insert(workspace_id, manager);
        Ok(())
    }

    pub fn contains(&self, workspace_id: &str) -> bool {
        self.workspaces.read().contains_key(workspace_id)
    }

    pub fn list(&self) -> Vec<(String, WorktreeManager)> {
        self.workspaces
            .read()
            .iter()
            .map(|(k, v)| (k.clone(), v.clone()))
            .collect()
    }

    pub fn manager(&self, workspace_id: &str) -> Result<WorktreeManager, WorktreeError> {
        let workspace_id = Self::validate_workspace_id(workspace_id)?;
        self.workspaces
            .read()
            .get(workspace_id)
            .cloned()
            .ok_or_else(|| WorktreeError::WorkspaceNotFound {
                workspace_id: workspace_id.to_string(),
            })
    }

    pub fn repo_root(&self, workspace_id: &str) -> Result<PathBuf, WorktreeError> {
        Ok(self.manager(workspace_id)?.repo_root().to_path_buf())
    }

    pub fn target_path(
        &self,
        workspace_id: &str,
        identity: &WorktreeIdentity,
    ) -> Result<PathBuf, WorktreeError> {
        self.manager(workspace_id)?
            .worktree_path_for(&identity.ws_id, &identity.slug)
    }

    pub fn resolve_worktree(
        &self,
        workspace_id: &str,
        identity: &WorktreeIdentity,
    ) -> Result<(WorktreeManager, Worktree), WorktreeError> {
        let manager = self.manager(workspace_id)?;
        let worktree = manager
            .find_worktree_by_slug(&identity.ws_id, &identity.slug)?
            .ok_or_else(|| WorktreeError::WorktreeIdentityNotFound {
                workspace_id: workspace_id.to_string(),
                ws_id: identity.ws_id.clone(),
                slug: identity.slug.clone(),
            })?;
        manager.canonical_allowed_path(&worktree.path)?;
        Ok((manager, worktree))
    }

    pub fn resolve_terminal_target(
        &self,
        workspace_id: &str,
        identity: Option<&WorktreeIdentity>,
    ) -> Result<(WorktreeManager, PathBuf), WorktreeError> {
        if let Some(identity) = identity {
            let (manager, worktree) = self.resolve_worktree(workspace_id, identity)?;
            let path = manager.canonical_allowed_path(&worktree.path)?;
            return Ok((manager, path));
        }

        let manager = self.manager(workspace_id)?;
        let path = manager.repo_root().to_path_buf();
        Ok((manager, path))
    }
}

use crate::terminal::{session::PtySessionConfig, PtyError, PtySession, PtySessionState, TerminalSignal};
use crate::worktree::manager::WriterLeaseGuard;
use crate::worktree::{WorktreeError, WorktreeManager};
use parking_lot::{Mutex, RwLock};
use portable_pty::{native_pty_system, CommandBuilder, PtySize, PtySystem};
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;
use std::time::Duration;
use tokio::sync::mpsc;
use uuid::Uuid;

const LIFECYCLE_POLL_INTERVAL: Duration = Duration::from_millis(20);
const READER_SHUTDOWN_TIMEOUT: Duration = Duration::from_secs(2);

#[derive(Clone)]
pub struct PtyManager {
    sessions: Arc<RwLock<HashMap<String, Arc<PtySession>>>>,
    pty_system: Arc<Mutex<Box<dyn PtySystem + Send>>>,
}

impl Default for PtyManager {
    fn default() -> Self {
        Self::new()
    }
}

impl PtyManager {
    pub fn new() -> Self {
        Self {
            sessions: Arc::new(RwLock::new(HashMap::new())),
            pty_system: Arc::new(Mutex::new(native_pty_system())),
        }
    }

    pub fn spawn(
        &self,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
    ) -> Result<(String, mpsc::Receiver<Vec<u8>>), PtyError> {
        let session_id = Uuid::new_v4().to_string();
        let rx = self.spawn_with_id(session_id.clone(), cmd, cols, rows)?;
        Ok((session_id, rx))
    }

    pub fn spawn_shell(
        &self,
        cols: u16,
        rows: u16,
    ) -> Result<(String, mpsc::Receiver<Vec<u8>>), PtyError> {
        let cmd = CommandBuilder::new_default_prog();
        self.spawn(cmd, cols, rows)
    }

    pub fn spawn_in_worktree(
        &self,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
        worktree_manager: &WorktreeManager,
        worktree_path: &Path,
    ) -> Result<(String, mpsc::Receiver<Vec<u8>>), PtyError> {
        let session_id = Uuid::new_v4().to_string();
        let lease = match worktree_manager.acquire_writer_lease(worktree_path, &session_id) {
            Ok(guard) => guard,
            Err(WorktreeError::WriterAlreadyActive { path, owner_id }) => {
                // If the previous owner session has already ended or is not active in this PtyManager,
                // automatically reclaim the lease.
                if self.get_session(&owner_id).is_none() {
                    let _ = worktree_manager.release_writer(&path, &owner_id);
                    worktree_manager
                        .acquire_writer_lease(worktree_path, &session_id)
                        .map_err(|error| PtyError::Other(error.to_string()))?
                } else {
                    return Err(PtyError::Other(format!(
                        "Worktree '{}' already has active writer '{}'",
                        path.display(),
                        owner_id
                    )));
                }
            }
            Err(error) => return Err(PtyError::Other(error.to_string())),
        };
        let rx = self.spawn_with_id_and_lease(
            session_id.clone(),
            cmd,
            cols,
            rows,
            Some(lease),
        )?;
        Ok((session_id, rx))
    }

    pub fn spawn_with_id(
        &self,
        session_id: impl Into<String>,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
    ) -> Result<mpsc::Receiver<Vec<u8>>, PtyError> {
        self.spawn_with_id_and_lease(session_id.into(), cmd, cols, rows, None)
    }

    fn spawn_with_id_and_lease(
        &self,
        session_id: String,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
        writer_lease: Option<WriterLeaseGuard>,
    ) -> Result<mpsc::Receiver<Vec<u8>>, PtyError> {
        if self.has_session(&session_id) {
            return Err(PtyError::Other(format!(
                "PTY session '{session_id}' already exists"
            )));
        }

        let pty_size = PtySize {
            rows,
            cols,
            pixel_width: 0,
            pixel_height: 0,
        };

        let pair = {
            let pty_system = self.pty_system.lock();
            pty_system
                .openpty(pty_size)
                .map_err(|e| PtyError::PtyCreationError(e.to_string()))?
        };

        let reader = pair
            .master
            .try_clone_reader()
            .map_err(|e| PtyError::IoError(format!("Failed to clone reader: {e}")))?;

        let writer = pair
            .master
            .take_writer()
            .map_err(|e| PtyError::IoError(format!("Failed to take writer: {e}")))?;

        let child = pair
            .slave
            .spawn_command(cmd)
            .map_err(|e| PtyError::SpawnError(format!("Failed to spawn command: {e}")))?;

        drop(pair.slave);

        let (tx, rx) = mpsc::channel::<Vec<u8>>(1024);
        let session = Arc::new(PtySession::new(PtySessionConfig {
            id: session_id.clone(),
            master: pair.master,
            child,
            writer,
            reader,
            cols,
            rows,
            tx,
            writer_lease,
        }));

        self.sessions
            .write()
            .insert(session_id.clone(), Arc::clone(&session));
        session.mark_running();
        self.start_lifecycle_watcher(session_id);
        Ok(rx)
    }

    fn start_lifecycle_watcher(&self, session_id: String) {
        let manager = self.clone();
        tokio::spawn(async move {
            loop {
                let Some(session) = manager.get_session(&session_id) else {
                    break;
                };

                match session.state() {
                    PtySessionState::Exited { .. } | PtySessionState::Failed { .. } => {
                        session.release_writer_lease();
                        session.close_output();
                        manager.remove_from_registry(&session_id);
                        break;
                    }
                    PtySessionState::Closing => {
                        tokio::time::sleep(LIFECYCLE_POLL_INTERVAL).await;
                        continue;
                    }
                    PtySessionState::Starting | PtySessionState::Running => {}
                }

                match session.poll_exit_code() {
                    Ok(Some(code)) => {
                        manager.finalize_natural_exit(&session_id, code).await;
                        break;
                    }
                    Ok(None)
                        if session.output_receiver_closed() || session.is_reader_finished() =>
                    {
                        if let Err(error) = manager.close_session(&session_id).await {
                            tracing::debug!(
                                "PTY receiver-drop cleanup failed for {}: {}",
                                session_id,
                                error
                            );
                        }
                        break;
                    }
                    Ok(None) => {}
                    Err(error) => {
                        session.mark_failed(error.to_string());
                        session.close_io();
                        session.release_writer_lease();
                        session.close_output();
                        manager.remove_from_registry(&session_id);
                        break;
                    }
                }

                tokio::time::sleep(LIFECYCLE_POLL_INTERVAL).await;
            }
        });
    }

    async fn finalize_natural_exit(&self, session_id: &str, code: i32) {
        let Some(session) = self.get_session(session_id) else {
            return;
        };
        if !session.begin_closing() {
            return;
        }

        session.close_io();
        let _ = Self::join_reader_bounded(&session).await;
        session.release_writer_lease();
        session.mark_exited(Some(code));
        session.close_output();
        self.remove_from_registry(session_id);
    }

    async fn join_reader_bounded(session: &Arc<PtySession>) -> Result<(), PtyError> {
        let Some(mut reader_task) = session.take_reader_task() else {
            return Ok(());
        };

        match tokio::time::timeout(READER_SHUTDOWN_TIMEOUT, &mut reader_task).await {
            Ok(Ok(())) => Ok(()),
            Ok(Err(error)) => Err(PtyError::Other(format!(
                "PTY reader task failed: {error}"
            ))),
            Err(_) => {
                reader_task.abort();
                Err(PtyError::Other(
                    "Timed out waiting for PTY reader shutdown".into(),
                ))
            }
        }
    }

    pub async fn close_session(&self, session_id: &str) -> Result<(), PtyError> {
        let Some(session) = self.get_session(session_id) else {
            return Ok(());
        };

        if !session.begin_closing() {
            if matches!(
                session.state(),
                PtySessionState::Exited { .. } | PtySessionState::Failed { .. }
            ) {
                session.release_writer_lease();
                session.close_output();
                self.remove_from_registry(session_id);
                return Ok(());
            }

            let deadline = tokio::time::Instant::now() + READER_SHUTDOWN_TIMEOUT;
            while tokio::time::Instant::now() < deadline {
                if !self.has_session(session_id) {
                    return Ok(());
                }
                tokio::time::sleep(LIFECYCLE_POLL_INTERVAL).await;
            }
            return Err(PtyError::Other(format!(
                "Timed out waiting for concurrent close of session '{session_id}'"
            )));
        }

        let mut first_error: Option<PtyError> = None;
        let mut exit_code = match session.poll_exit_code() {
            Ok(code) => code,
            Err(error) => {
                first_error = Some(error);
                None
            }
        };

        if exit_code.is_none() {
            if let Err(signal_error) = session.signal(TerminalSignal::Terminate) {
                if let Err(kill_error) = session.kill() {
                    first_error = Some(PtyError::KillError(format!(
                        "{signal_error}; fallback kill failed: {kill_error}"
                    )));
                }
            }
        }

        session.close_io();

        if let Err(reader_error) = Self::join_reader_bounded(&session).await {
            let _ = session.signal(TerminalSignal::Kill).or_else(|_| session.kill());
            if first_error.is_none() {
                first_error = Some(reader_error);
            }
        }

        if exit_code.is_none() && !session.is_reaped() {
            let session_for_wait = Arc::clone(&session);
            match tokio::task::spawn_blocking(move || session_for_wait.wait_and_reap()).await {
                Ok(Ok(code)) => exit_code = code,
                Ok(Err(error)) => {
                    if first_error.is_none() {
                        first_error = Some(error);
                    }
                }
                Err(error) => {
                    if first_error.is_none() {
                        first_error = Some(PtyError::Other(format!(
                            "PTY child reap task failed: {error}"
                        )));
                    }
                }
            }
        }

        session.release_writer_lease();

        if let Some(error) = first_error {
            session.mark_failed(error.to_string());
            session.close_output();
            self.remove_from_registry(session_id);
            return Err(error);
        }

        session.mark_exited(exit_code);
        session.close_output();
        self.remove_from_registry(session_id);
        Ok(())
    }

    pub fn write_input(&self, session_id: &str, data: &[u8]) -> Result<(), PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        session.write_input(data)
    }

    pub fn resize(&self, session_id: &str, cols: u16, rows: u16) -> Result<(), PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        session.resize(cols, rows)
    }

    pub fn kill(&self, session_id: &str) -> Result<(), PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        session.kill()
    }

    pub fn signal(&self, session_id: &str, signal: TerminalSignal) -> Result<(), PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        session.signal(signal)
    }

    pub fn get_session(&self, session_id: &str) -> Option<Arc<PtySession>> {
        self.sessions.read().get(session_id).cloned()
    }

    pub fn has_session(&self, session_id: &str) -> bool {
        self.sessions.read().contains_key(session_id)
    }

    fn remove_from_registry(&self, session_id: &str) -> Option<Arc<PtySession>> {
        self.sessions.write().remove(session_id)
    }

    pub fn list_sessions(&self) -> Vec<String> {
        self.sessions.read().keys().cloned().collect()
    }

    pub fn session_count(&self) -> usize {
        self.sessions.read().len()
    }

    pub fn is_alive(&self, session_id: &str) -> Result<bool, PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        Ok(session.is_alive())
    }
}

use crate::terminal::PtyError;
use crate::worktree::manager::WriterLeaseGuard;
use parking_lot::Mutex;
use portable_pty::{Child, MasterPty, PtySize};
use std::io::{Read, Write};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use tokio::sync::mpsc;
use tokio::task::JoinHandle;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PtySessionState {
    Starting,
    Running,
    Closing,
    Exited { code: Option<i32> },
    Failed { reason: String },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum TerminalSignal {
    Interrupt,
    Terminate,
    Kill,
}

pub(crate) struct PtySessionConfig {
    pub id: String,
    pub master: Box<dyn MasterPty + Send>,
    pub child: Box<dyn Child + Send + Sync>,
    pub writer: Box<dyn Write + Send>,
    pub reader: Box<dyn Read + Send>,
    pub cols: u16,
    pub rows: u16,
    pub tx: mpsc::Sender<Vec<u8>>,
    pub writer_lease: Option<WriterLeaseGuard>,
}

pub struct PtySession {
    pub id: String,
    master: Arc<Mutex<Option<Box<dyn MasterPty + Send>>>>,
    writer: Arc<Mutex<Option<Box<dyn Write + Send>>>>,
    child: Arc<Mutex<Option<Box<dyn Child + Send + Sync>>>>,
    reader_task: Arc<Mutex<Option<JoinHandle<()>>>>,
    output_tx: Arc<Mutex<Option<mpsc::Sender<Vec<u8>>>>>,
    writer_lease: Arc<Mutex<Option<WriterLeaseGuard>>>,
    reader_finished: Arc<AtomicBool>,
    reaped: Arc<AtomicBool>,
    state: Arc<Mutex<PtySessionState>>,
    cols: Arc<Mutex<u16>>,
    rows: Arc<Mutex<u16>>,
}

impl PtySession {
    pub(crate) fn new(config: PtySessionConfig) -> Self {
        let output_tx = Arc::new(Mutex::new(Some(config.tx)));
        let reader_tx = output_tx
            .lock()
            .as_ref()
            .expect("output sender must exist while starting reader")
            .clone();
        let reader = config.reader;
        let reader_finished = Arc::new(AtomicBool::new(false));
        let reader_finished_task = Arc::clone(&reader_finished);
        let reader_task = tokio::task::spawn_blocking(move || {
            let mut reader = reader;
            let mut buf = [0u8; 4096];
            loop {
                match reader.read(&mut buf) {
                    Ok(0) => break,
                    Ok(n) => {
                        if reader_tx.blocking_send(buf[..n].to_vec()).is_err() {
                            break;
                        }
                    }
                    Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                    Err(_) => break,
                }
            }
            reader_finished_task.store(true, Ordering::Release);
        });

        Self {
            id: config.id,
            master: Arc::new(Mutex::new(Some(config.master))),
            writer: Arc::new(Mutex::new(Some(config.writer))),
            child: Arc::new(Mutex::new(Some(config.child))),
            reader_task: Arc::new(Mutex::new(Some(reader_task))),
            output_tx,
            writer_lease: Arc::new(Mutex::new(config.writer_lease)),
            reader_finished,
            reaped: Arc::new(AtomicBool::new(false)),
            state: Arc::new(Mutex::new(PtySessionState::Starting)),
            cols: Arc::new(Mutex::new(config.cols)),
            rows: Arc::new(Mutex::new(config.rows)),
        }
    }

    pub fn id(&self) -> &str {
        &self.id
    }

    pub fn state(&self) -> PtySessionState {
        self.state.lock().clone()
    }

    pub(crate) fn mark_running(&self) {
        let mut state = self.state.lock();
        if matches!(*state, PtySessionState::Starting) {
            *state = PtySessionState::Running;
        }
    }

    pub(crate) fn begin_closing(&self) -> bool {
        let mut state = self.state.lock();
        match *state {
            PtySessionState::Starting | PtySessionState::Running => {
                *state = PtySessionState::Closing;
                true
            }
            PtySessionState::Closing
            | PtySessionState::Exited { .. }
            | PtySessionState::Failed { .. } => false,
        }
    }

    pub(crate) fn mark_exited(&self, code: Option<i32>) {
        *self.state.lock() = PtySessionState::Exited { code };
    }

    pub(crate) fn mark_failed(&self, reason: impl Into<String>) {
        *self.state.lock() = PtySessionState::Failed {
            reason: reason.into(),
        };
    }

    pub fn pid(&self) -> Option<u32> {
        self.child
            .lock()
            .as_ref()
            .and_then(|child| child.process_id())
    }

    pub fn writer_worktree(&self) -> Option<PathBuf> {
        self.writer_lease
            .lock()
            .as_ref()
            .map(|lease| lease.canonical_path().to_path_buf())
    }

    pub fn writer_owner_id(&self) -> Option<String> {
        self.writer_lease
            .lock()
            .as_ref()
            .map(|lease| lease.owner_id().to_string())
    }

    pub fn write_input(&self, data: &[u8]) -> Result<(), PtyError> {
        let mut writer = self.writer.lock();
        let writer = writer
            .as_mut()
            .ok_or_else(|| PtyError::IoError("PTY writer is closed".into()))?;
        writer
            .write_all(data)
            .map_err(|e| PtyError::IoError(format!("Write failed: {e}")))?;
        writer
            .flush()
            .map_err(|e| PtyError::IoError(format!("Flush failed: {e}")))?;
        Ok(())
    }

    pub fn resize(&self, cols: u16, rows: u16) -> Result<(), PtyError> {
        let size = PtySize {
            rows,
            cols,
            pixel_width: 0,
            pixel_height: 0,
        };
        let master = self.master.lock();
        let master = master
            .as_ref()
            .ok_or_else(|| PtyError::ResizeError("PTY master is closed".into()))?;
        master
            .resize(size)
            .map_err(|e| PtyError::ResizeError(format!("Resize failed: {e}")))?;
        *self.cols.lock() = cols;
        *self.rows.lock() = rows;
        Ok(())
    }

    pub fn get_size(&self) -> (u16, u16) {
        (*self.cols.lock(), *self.rows.lock())
    }

    pub fn kill(&self) -> Result<(), PtyError> {
        let mut child = self.child.lock();
        let Some(child) = child.as_mut() else {
            return Ok(());
        };
        child
            .kill()
            .map_err(|e| PtyError::KillError(format!("Kill failed: {e}")))
    }

    #[cfg(unix)]
    pub fn signal(&self, signal: TerminalSignal) -> Result<(), PtyError> {
        if signal == TerminalSignal::Interrupt {
            // A literal VINTR byte goes through the PTY line discipline, which directs
            // SIGINT to the terminal's current foreground process group.
            return self.write_input(&[0x03]);
        }

        let pid = self
            .pid()
            .ok_or_else(|| PtyError::KillError("PID not available for signal".into()))?;
        let sig = match signal {
            TerminalSignal::Interrupt => libc::SIGINT,
            TerminalSignal::Terminate => libc::SIGTERM,
            TerminalSignal::Kill => libc::SIGKILL,
        };

        // portable-pty creates the child as the PTY session/process-group leader on Unix.
        // Addressing the negative pid signals the whole job-control process group rather
        // than only the shell process.
        let result = unsafe { libc::kill(-(pid as i32), sig) };
        if result == 0 {
            return Ok(());
        }

        Err(PtyError::KillError(format!(
            "Failed to send signal {signal:?} to process group {pid}: {}",
            std::io::Error::last_os_error()
        )))
    }

    #[cfg(not(unix))]
    pub fn signal(&self, signal: TerminalSignal) -> Result<(), PtyError> {
        match signal {
            TerminalSignal::Interrupt | TerminalSignal::Terminate | TerminalSignal::Kill => {
                self.kill()
            }
        }
    }

    pub(crate) fn poll_exit_code(&self) -> Result<Option<i32>, PtyError> {
        let mut child_slot = self.child.lock();
        let Some(child) = child_slot.as_mut() else {
            return Ok(match self.state() {
                PtySessionState::Exited { code } => code,
                _ => None,
            });
        };

        let status = child
            .try_wait()
            .map_err(|e| PtyError::Other(format!("try_wait failed: {e}")))?;
        let Some(status) = status else {
            return Ok(None);
        };

        let code = status.exit_code() as i32;
        child_slot.take();
        self.reaped.store(true, Ordering::Release);
        Ok(Some(code))
    }

    pub(crate) fn wait_and_reap(&self) -> Result<Option<i32>, PtyError> {
        let mut child_slot = self.child.lock();
        let Some(mut child) = child_slot.take() else {
            return Ok(match self.state() {
                PtySessionState::Exited { code } => code,
                _ => None,
            });
        };

        let result = child
            .wait()
            .map(|status| Some(status.exit_code() as i32))
            .map_err(|e| PtyError::Other(format!("wait failed: {e}")));
        self.reaped.store(true, Ordering::Release);
        result
    }

    pub fn is_alive(&self) -> bool {
        matches!(self.poll_exit_code(), Ok(None)) && !self.is_reaped()
    }

    pub fn is_reaped(&self) -> bool {
        self.reaped.load(Ordering::Acquire)
    }

    pub fn is_reader_finished(&self) -> bool {
        self.reader_finished.load(Ordering::Acquire)
    }

    pub(crate) fn output_receiver_closed(&self) -> bool {
        self.output_tx
            .lock()
            .as_ref()
            .map(mpsc::Sender::is_closed)
            .unwrap_or(true)
    }

    pub(crate) fn close_output(&self) {
        self.output_tx.lock().take();
    }

    pub(crate) fn close_io(&self) {
        self.writer.lock().take();
        self.master.lock().take();
    }

    pub(crate) fn release_writer_lease(&self) {
        self.writer_lease.lock().take();
    }

    pub(crate) fn take_reader_task(&self) -> Option<JoinHandle<()>> {
        self.reader_task.lock().take()
    }
}

impl Drop for PtySession {
    fn drop(&mut self) {
        self.writer.lock().take();
        self.master.lock().take();
        self.output_tx.lock().take();
        self.writer_lease.lock().take();
        if let Some(handle) = self.reader_task.lock().take() {
            handle.abort();
        }
    }
}

use crate::terminal::output_hub::TerminalOutputHub;
use crate::terminal::{PtyError, PtyManager, PtySession, TerminalSignal};
use crate::worktree::manager::WorktreeManager;
use portable_pty::CommandBuilder;
use std::path::Path;
use std::sync::Arc;
use tokio::sync::broadcast;

#[derive(Clone)]
pub struct TerminalService {
    pty_manager: Arc<PtyManager>,
    output_hub: Arc<TerminalOutputHub>,
}

impl Default for TerminalService {
    fn default() -> Self {
        Self::new(Arc::new(PtyManager::new()), Arc::new(TerminalOutputHub::default()))
    }
}

impl TerminalService {
    pub fn new(pty_manager: Arc<PtyManager>, output_hub: Arc<TerminalOutputHub>) -> Self {
        Self {
            pty_manager,
            output_hub,
        }
    }

    pub fn pty_manager(&self) -> &Arc<PtyManager> {
        &self.pty_manager
    }

    pub fn output_hub(&self) -> &Arc<TerminalOutputHub> {
        &self.output_hub
    }

    pub fn spawn_in_worktree(
        &self,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
        worktree_manager: &WorktreeManager,
        worktree_path: &Path,
    ) -> Result<(String, broadcast::Receiver<Vec<u8>>), PtyError> {
        let (session_id, mut pty_rx) = self
            .pty_manager
            .spawn_in_worktree(cmd, cols, rows, worktree_manager, worktree_path)?;

        let broadcast_rx = self.output_hub.register_session(&session_id);

        // Spawn output pump task from PTY reader to OutputHub
        let output_hub = Arc::clone(&self.output_hub);
        let session_id_clone = session_id.clone();
        tokio::spawn(async move {
            while let Some(chunk) = pty_rx.recv().await {
                output_hub.publish(&session_id_clone, chunk);
            }
        });

        Ok((session_id, broadcast_rx))
    }

    pub fn attach(&self, session_id: &str) -> Result<(Vec<u8>, broadcast::Receiver<Vec<u8>>), PtyError> {
        if !self.pty_manager.list_sessions().contains(&session_id.to_string()) {
            return Err(PtyError::SessionNotFound(session_id.to_string()));
        }

        self.output_hub
            .subscribe(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))
    }

    pub fn write_input(&self, session_id: &str, data: &[u8]) -> Result<(), PtyError> {
        self.pty_manager.write_input(session_id, data)
    }

    pub fn resize(&self, session_id: &str, cols: u16, rows: u16) -> Result<(), PtyError> {
        self.pty_manager.resize(session_id, cols, rows)
    }

    pub fn signal(&self, session_id: &str, signal: TerminalSignal) -> Result<(), PtyError> {
        self.pty_manager.signal(session_id, signal)
    }

    pub async fn close_session(&self, session_id: &str) -> Result<(), PtyError> {
        self.output_hub.remove_session(session_id);
        self.pty_manager.close_session(session_id).await
    }

    pub fn list_sessions(&self) -> Vec<String> {
        self.pty_manager.list_sessions()
    }

    pub fn get_session(&self, session_id: &str) -> Option<Arc<PtySession>> {
        self.pty_manager.get_session(session_id)
    }
}

use parking_lot::RwLock;
use std::collections::{HashMap, VecDeque};
use std::sync::Arc;
use tokio::sync::broadcast;

const DEFAULT_BUFFER_CAPACITY: usize = 512 * 1024; // 512 KiB
const BROADCAST_CAPACITY: usize = 1024;

pub struct BoundedBuffer {
    capacity: usize,
    chunks: VecDeque<Vec<u8>>,
    current_size: usize,
}

impl BoundedBuffer {
    pub fn new(capacity: usize) -> Self {
        Self {
            capacity,
            chunks: VecDeque::new(),
            current_size: 0,
        }
    }

    pub fn push(&mut self, chunk: Vec<u8>) {
        if chunk.is_empty() {
            return;
        }
        self.current_size += chunk.len();
        self.chunks.push_back(chunk);

        while self.current_size > self.capacity && !self.chunks.is_empty() {
            if let Some(front) = self.chunks.pop_front() {
                self.current_size -= front.len();
            }
        }
    }

    pub fn snapshot(&self) -> Vec<u8> {
        let mut out = Vec::with_capacity(self.current_size);
        for chunk in &self.chunks {
            out.extend_from_slice(chunk);
        }
        out
    }
}

struct SessionHub {
    buffer: BoundedBuffer,
    sender: broadcast::Sender<Vec<u8>>,
}

#[derive(Clone)]
pub struct TerminalOutputHub {
    sessions: Arc<RwLock<HashMap<String, Arc<RwLock<SessionHub>>>>>,
    capacity: usize,
}

impl Default for TerminalOutputHub {
    fn default() -> Self {
        Self::new(DEFAULT_BUFFER_CAPACITY)
    }
}

impl TerminalOutputHub {
    pub fn new(capacity: usize) -> Self {
        Self {
            sessions: Arc::new(RwLock::new(HashMap::new())),
            capacity,
        }
    }

    pub fn register_session(&self, session_id: &str) -> broadcast::Receiver<Vec<u8>> {
        let (tx, rx) = broadcast::channel(BROADCAST_CAPACITY);
        let hub = SessionHub {
            buffer: BoundedBuffer::new(self.capacity),
            sender: tx,
        };
        self.sessions
            .write()
            .insert(session_id.to_string(), Arc::new(RwLock::new(hub)));
        rx
    }

    pub fn publish(&self, session_id: &str, chunk: Vec<u8>) {
        let session_hub = {
            let sessions = self.sessions.read();
            sessions.get(session_id).cloned()
        };

        if let Some(hub) = session_hub {
            let mut hub = hub.write();
            hub.buffer.push(chunk.clone());
            // It is okay if there are no active receivers; send returns Err in that case
            let _ = hub.sender.send(chunk);
        }
    }

    pub fn subscribe(&self, session_id: &str) -> Option<(Vec<u8>, broadcast::Receiver<Vec<u8>>)> {
        let session_hub = {
            let sessions = self.sessions.read();
            sessions.get(session_id).cloned()
        }?;

        let hub = session_hub.read();
        let history = hub.buffer.snapshot();
        let rx = hub.sender.subscribe();
        Some((history, rx))
    }

    pub fn remove_session(&self, session_id: &str) {
        self.sessions.write().remove(session_id);
    }

    pub fn has_session(&self, session_id: &str) -> bool {
        self.sessions.read().contains_key(session_id)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_output_hub_replay_and_broadcast() {
        let hub = TerminalOutputHub::new(1024);
        let session_id = "test-session";
        let _initial_rx = hub.register_session(session_id);

        hub.publish(session_id, b"hello ".to_vec());
        hub.publish(session_id, b"world\n".to_vec());

        let (history, mut rx) = hub.subscribe(session_id).expect("session exists");
        assert_eq!(history, b"hello world\n");

        hub.publish(session_id, b"live chunk".to_vec());
        let received = rx.recv().await.expect("received live message");
        assert_eq!(received, b"live chunk");
    }

    #[tokio::test]
    async fn test_bounded_buffer_overflow() {
        let mut buffer = BoundedBuffer::new(10);
        buffer.push(b"12345".to_vec());
        buffer.push(b"67890".to_vec());
        buffer.push(b"abcdef".to_vec());

        let snap = buffer.snapshot();
        assert!(snap.len() <= 16); // pops chunks until under capacity
        assert!(snap.ends_with(b"abcdef"));
    }
}

use crate::ipc::{run_blocking, IpcError};
use crate::worktree::{
    BranchDeletionPreview, CreateWorktreeOptions, DirtyState, Worktree, WorktreeIdentity,
    WorkspaceRegistry,
};
use serde::{Deserialize, Serialize};
use tauri::{AppHandle, Emitter, Runtime, State};

pub const WORKTREE_CHANGED_EVENT: &str = "worktree_changed";

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct CreateWorktreeRequest {
    pub workspace_id: String,
    pub worktree: WorktreeIdentity,
    pub base_ref: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct DeleteWorktreeRequest {
    pub workspace_id: String,
    pub worktree: WorktreeIdentity,
    pub delete_branch: Option<bool>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct WorktreeStatusRequest {
    pub workspace_id: String,
    pub worktree: WorktreeIdentity,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum WorktreeChangeKind {
    Created,
    Deleted,
    DestructivelyDeleted,
    #[serde(rename = "dirtyChanged")]
    DirtyChanged,
    Pruned,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct WorktreeChangedPayload {
    pub workspace_id: String,
    pub worktree: WorktreeIdentity,
    pub kind: WorktreeChangeKind,
}

fn emit_worktree_changed<R: Runtime>(
    app: &AppHandle<R>,
    workspace_id: String,
    worktree: WorktreeIdentity,
    kind: WorktreeChangeKind,
) -> Result<(), IpcError> {
    app.emit(
        WORKTREE_CHANGED_EVENT,
        WorktreeChangedPayload {
            workspace_id,
            worktree,
            kind,
        },
    )
    .map_err(|error| IpcError::internal(format!("failed to emit worktree_changed: {error}")))
}

#[tauri::command]
pub async fn cmd_worktree_list(
    registry: State<'_, WorkspaceRegistry>,
    workspace_id: String,
) -> Result<Vec<Worktree>, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || {
        let manager = registry.manager(&workspace_id).map_err(IpcError::from)?;
        manager.list_worktrees().map_err(IpcError::from)
    })
    .await
}

#[tauri::command]
pub async fn cmd_worktree_create<R: Runtime>(
    app: AppHandle<R>,
    registry: State<'_, WorkspaceRegistry>,
    request: CreateWorktreeRequest,
) -> Result<Worktree, IpcError> {
    let registry = (*registry).clone();
    let workspace_id = request.workspace_id.clone();
    let identity = request.worktree.clone();
    let event_workspace_id = workspace_id.clone();
    let event_identity = identity.clone();

    let created = run_blocking(move || {
        let manager = registry.manager(&workspace_id).map_err(IpcError::from)?;
        let target = manager
            .worktree_path_for(&identity.ws_id, &identity.slug)
            .map_err(IpcError::from)?;
        let mut options =
            CreateWorktreeOptions::new(identity.ws_id.clone(), identity.slug.clone(), target);
        if let Some(base_ref) = request.base_ref {
            options = options.with_base_ref(base_ref);
        }
        manager.create_worktree(options).map_err(IpcError::from)
    })
    .await?;

    emit_worktree_changed(
        &app,
        event_workspace_id,
        event_identity,
        WorktreeChangeKind::Created,
    )?;
    Ok(created)
}

async fn delete_worktree<R: Runtime>(
    app: AppHandle<R>,
    registry: State<'_, WorkspaceRegistry>,
    request: DeleteWorktreeRequest,
    destructive: bool,
) -> Result<(), IpcError> {
    let registry = (*registry).clone();
    let workspace_id = request.workspace_id.clone();
    let identity = request.worktree.clone();
    let delete_branch = request.delete_branch.unwrap_or(false);
    let event_workspace_id = workspace_id.clone();
    let event_identity = identity.clone();

    let pruned = run_blocking(move || {
        let (manager, worktree) = registry
            .resolve_worktree(&workspace_id, &identity)
            .map_err(IpcError::from)?;
        manager
            .delete_worktree_and_branch_with_prune_status(
                &worktree.path,
                delete_branch,
                destructive,
            )
            .map_err(IpcError::from)
    })
    .await?;

    emit_worktree_changed(
        &app,
        event_workspace_id.clone(),
        event_identity.clone(),
        if destructive {
            WorktreeChangeKind::DestructivelyDeleted
        } else {
            WorktreeChangeKind::Deleted
        },
    )?;
    if pruned {
        emit_worktree_changed(
            &app,
            event_workspace_id,
            event_identity,
            WorktreeChangeKind::Pruned,
        )?;
    }
    Ok(())
}

#[tauri::command]
pub async fn cmd_worktree_delete<R: Runtime>(
    app: AppHandle<R>,
    registry: State<'_, WorkspaceRegistry>,
    request: DeleteWorktreeRequest,
) -> Result<(), IpcError> {
    delete_worktree(app, registry, request, false).await
}

#[tauri::command]
pub async fn cmd_worktree_delete_destructive<R: Runtime>(
    app: AppHandle<R>,
    registry: State<'_, WorkspaceRegistry>,
    request: DeleteWorktreeRequest,
) -> Result<(), IpcError> {
    delete_worktree(app, registry, request, true).await
}

#[tauri::command]
pub async fn cmd_worktree_delete_preview(
    registry: State<'_, WorkspaceRegistry>,
    request: WorktreeStatusRequest,
) -> Result<BranchDeletionPreview, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || {
        let (manager, worktree) = registry
            .resolve_worktree(&request.workspace_id, &request.worktree)
            .map_err(IpcError::from)?;
        manager
            .branch_deletion_preview(&worktree.path)
            .map_err(IpcError::from)
    })
    .await
}

#[tauri::command]
pub async fn cmd_worktree_status<R: Runtime>(
    app: AppHandle<R>,
    registry: State<'_, WorkspaceRegistry>,
    request: WorktreeStatusRequest,
) -> Result<DirtyState, IpcError> {
    let registry = (*registry).clone();
    let workspace_id = request.workspace_id.clone();
    let identity = request.worktree.clone();
    let event_workspace_id = workspace_id.clone();
    let event_identity = identity.clone();

    let (status, changed) = run_blocking(move || {
        let (manager, worktree) = registry
            .resolve_worktree(&workspace_id, &identity)
            .map_err(IpcError::from)?;
        manager
            .observe_dirty_state(&worktree.path)
            .map_err(IpcError::from)
    })
    .await?;

    if changed {
        emit_worktree_changed(
            &app,
            event_workspace_id,
            event_identity,
            WorktreeChangeKind::DirtyChanged,
        )?;
    }
    Ok(status)
}

use crate::terminal::PtyError;
use crate::worktree::WorktreeError;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum IpcErrorCode {
    DirtyWorktree,
    WriterAlreadyActive,
    WriterLeaseOwnerMismatch,
    UnmergedBranch,
    WorkspaceNotFound,
    WorkspaceAlreadyRegistered,
    WorktreeNotFound,
    WorktreeAlreadyExists,
    PathOutsideWorkspace,
    InvalidPath,
    InvalidNamespace,
    InvalidRepoRoot,
    GitError,
    IoError,
    ParseError,
    SessionNotFound,
    BrowserNotFound,
    BrowserUrlInvalid,
    BrowserUrlSchemeDenied,
    BrowserBoundsInvalid,
    BrowserCreateFailed,
    BrowserNavigationFailed,
    BrowserHistoryFailed,
    BrowserCloseFailed,
    PtyCreationError,
    PtySpawnError,
    PtyIoError,
    PtyResizeError,
    PtyKillError,
    ChannelError,
    InternalError,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct IpcError {
    pub code: IpcErrorCode,
    pub message: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub details: Option<Value>,
}

impl IpcError {
    pub fn new(code: IpcErrorCode, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
            details: None,
        }
    }

    pub fn with_details(mut self, details: Value) -> Self {
        self.details = Some(details);
        self
    }

    pub fn internal(message: impl Into<String>) -> Self {
        Self::new(IpcErrorCode::InternalError, message)
    }
}

impl From<WorktreeError> for IpcError {
    fn from(error: WorktreeError) -> Self {
        let message = error.to_string();
        match error {
            WorktreeError::DirtyWorktree {
                path,
                count,
                files,
            } => Self::new(IpcErrorCode::DirtyWorktree, message).with_details(json!({
                "path": path,
                "count": count,
                "files": files,
            })),
            WorktreeError::WriterAlreadyActive { path, owner_id } => {
                Self::new(IpcErrorCode::WriterAlreadyActive, message).with_details(json!({
                    "path": path,
                    "ownerId": owner_id,
                }))
            }
            WorktreeError::WriterLeaseOwnerMismatch {
                path,
                owner_id,
                requested_owner_id,
            } => Self::new(IpcErrorCode::WriterLeaseOwnerMismatch, message).with_details(json!({
                "path": path,
                "ownerId": owner_id,
                "requestedOwnerId": requested_owner_id,
            })),
            WorktreeError::UnmergedBranch { branch, head } => {
                Self::new(IpcErrorCode::UnmergedBranch, message).with_details(json!({
                    "branch": branch,
                    "head": head,
                }))
            }
            WorktreeError::WorkspaceNotFound { workspace_id } => {
                Self::new(IpcErrorCode::WorkspaceNotFound, message).with_details(json!({
                    "workspaceId": workspace_id,
                }))
            }
            WorktreeError::WorkspaceAlreadyRegistered { workspace_id } => {
                Self::new(IpcErrorCode::WorkspaceAlreadyRegistered, message).with_details(json!({
                    "workspaceId": workspace_id,
                }))
            }
            WorktreeError::WorktreeIdentityNotFound {
                workspace_id,
                ws_id,
                slug,
            } => Self::new(IpcErrorCode::WorktreeNotFound, message).with_details(json!({
                "workspaceId": workspace_id,
                "worktree": { "wsId": ws_id, "slug": slug },
            })),
            WorktreeError::PathOutsideWorkspace { path, root } => {
                Self::new(IpcErrorCode::PathOutsideWorkspace, message).with_details(json!({
                    "path": path,
                    "root": root,
                }))
            }
            WorktreeError::InvalidPath { path, reason } => {
                Self::new(IpcErrorCode::InvalidPath, message).with_details(json!({
                    "path": path,
                    "reason": reason,
                }))
            }
            WorktreeError::WorktreeNotFound { path } => {
                Self::new(IpcErrorCode::WorktreeNotFound, message)
                    .with_details(json!({ "path": path }))
            }
            WorktreeError::WorktreeAlreadyExists { path } => {
                Self::new(IpcErrorCode::WorktreeAlreadyExists, message)
                    .with_details(json!({ "path": path }))
            }
            WorktreeError::BranchAlreadyExists { branch } => {
                Self::new(IpcErrorCode::WorktreeAlreadyExists, message)
                    .with_details(json!({ "branch": branch }))
            }
            WorktreeError::InvalidNamespace { reason } => {
                Self::new(IpcErrorCode::InvalidNamespace, message)
                    .with_details(json!({ "reason": reason }))
            }
            WorktreeError::InvalidRepoRoot { path } => {
                Self::new(IpcErrorCode::InvalidRepoRoot, message)
                    .with_details(json!({ "path": path }))
            }
            WorktreeError::GitError {
                command,
                stderr,
                stdout: _,
                code,
            } => Self::new(IpcErrorCode::GitError, message).with_details(json!({
                "command": command,
                "stderr": stderr,
                "exitCode": code,
            })),
            WorktreeError::ParseError(_) => Self::new(IpcErrorCode::ParseError, message),
            WorktreeError::Io(_) => Self::new(IpcErrorCode::IoError, message),
        }
    }
}

impl From<PtyError> for IpcError {
    fn from(error: PtyError) -> Self {
        let code = match error {
            PtyError::SessionNotFound(_) => IpcErrorCode::SessionNotFound,
            PtyError::PtyCreationError(_) => IpcErrorCode::PtyCreationError,
            PtyError::SpawnError(_) => IpcErrorCode::PtySpawnError,
            PtyError::IoError(_) => IpcErrorCode::PtyIoError,
            PtyError::ResizeError(_) => IpcErrorCode::PtyResizeError,
            PtyError::KillError(_) => IpcErrorCode::PtyKillError,
            PtyError::ChannelError(_) => IpcErrorCode::ChannelError,
            PtyError::Other(_) => IpcErrorCode::InternalError,
        };
        Self::new(code, error.to_string())
    }
}

impl From<crate::browser::BrowserError> for IpcError {
    fn from(error: crate::browser::BrowserError) -> Self {
        let message = error.to_string();
        let code = match error {
            crate::browser::BrowserError::NotFound(_) => IpcErrorCode::BrowserNotFound,
            crate::browser::BrowserError::InvalidUrl(_) => IpcErrorCode::BrowserUrlInvalid,
            crate::browser::BrowserError::SchemeDenied(_) => IpcErrorCode::BrowserUrlSchemeDenied,
            crate::browser::BrowserError::InvalidBounds => IpcErrorCode::BrowserBoundsInvalid,
            crate::browser::BrowserError::UnsupportedProfile(_) => IpcErrorCode::InternalError,
            crate::browser::BrowserError::CreateFailed(_) => IpcErrorCode::BrowserCreateFailed,
            crate::browser::BrowserError::NavigationFailed(_) => IpcErrorCode::BrowserNavigationFailed,
            crate::browser::BrowserError::HistoryFailed(_) => IpcErrorCode::BrowserHistoryFailed,
            crate::browser::BrowserError::CloseFailed(_) => IpcErrorCode::BrowserCloseFailed,
            crate::browser::BrowserError::PlatformUnsupported(_) => IpcErrorCode::InternalError,
            crate::browser::BrowserError::Internal(_) => IpcErrorCode::InternalError,
        };
        Self::new(code, message)
    }
}


impl std::fmt::Display for IpcError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.message)
    }
}

